clc; clear; close all; [x, Fs] = audioread('names.wav'); if size(x,2) == 2 x = mean(x,2); end N = length(x); t = (0:N-1)/Fs; figure; plot(t, x); xlabel('Time (sec)'); ylabel('Amplitude'); title('Audio Signal in Time Domain'); grid on; Energy_time = sum(abs(x).^2); disp('Energy in Time Domain:'); disp(Energy_time); X = fft(x); X_shift = fftshift(X); f = (-N/2 : N/2-1)*(Fs/N); figure; plot(f, abs(X_shift)); xlabel('Frequency (Hz)'); ylabel('Magnitude'); title('Frequency Domain Representation'); grid on; Energy_freq = sum(abs(X).^2)/N; disp('Energy in Frequency Domain:'); disp(Energy_freq); Difference = abs(Energy_time - Energy_freq); disp('Difference between energies:'); disp(Difference); magnitude = abs(X_shift); [~, index] = max(magnitude); f_peak = f(index(1)); disp('Peak Frequency:'); disp(f_peak); BW_values = [50 150 300]; for k = 1:length(BW_values) BW = BW_values(k); X_filtered = X_shift; notch_region = abs(f - f_peak) < BW | abs(f + f_peak) < BW; X_filtered(notch_region) = 0; figure; plot(f, abs(X_filtered)); xlabel('Frequency (Hz)'); ylabel('Magnitude'); title(['Filtered Spectrum - BW = ' num2str(BW)]); grid on; X_inverse = ifftshift(X_filtered); x_filtered = real(ifft(X_inverse)); figure; plot(t, x_filtered); xlabel('Time (sec)'); ylabel('Amplitude'); title(['Filtered Signal - BW = ' num2str(BW)]); grid on; filename = ['filtered_BW_' num2str(BW) '.wav']; audiowrite(['filtered_BW_' num2str(BW) '.wav'], x_filtered, Fs); end